/* Dense switch intended to compile to an ARM64 jump table at -O2. */
extern int jt_a0(void);
extern int jt_a1(void);
extern int jt_a2(void);
extern int jt_a3(void);
extern int jt_a4(void);
extern int jt_a5(void);
